INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvhul6eo002soz9ngvudqyit', 'veh_prado_2018', '[{"area":"identity","title":"VIN & identity","titleKm":"អត្តសញ្ញាណ និងលេខសំគាល់","status":"NOT_VERIFIED","detail":"Chassis ending T8H229 provided in the listing matches the registration book images, but the vehicle has not been physically inspected by the platform, so identity is not independently confirmed.","detailKm":"លេខចាប់ចុង T8H229 ក្នុងបញ្ជីលក់ត្រូវគ្នានឹងរូបសៀវភៅចុះបញ្ជី ប៉ុន្តែវេទិកាមិនបានពិនិត្យរថយន្តដោយផ្ទាល់ទេ ដូច្នេះអត្តសញ្ញាណមិនអាចបញ្ជាក់ដោយឯករាជ្យបានទេ។","source":"Listing data + Registration book (platform-verified)","confidence":0.6},{"area":"registration","title":"Registration book","titleKm":"សៀវភៅចុះបញ្ជី","status":"VERIFIED","detail":"Registration book reviewed and platform-verified. Plate 1KH-8823 and owner details are internally consistent.","detailKm":"សៀវភៅចុះបញ្ជីត្រូវបានពិនិត្យនិងផ្ទៀងផ្ទាត់ដោយវេទិកា។ ស្លាកលេខ 1KH-8823 និងព័ត៌មានម្ចាស់ត្រូវគ្នា។","source":"Registration book (platform-verified)","confidence":0.95},{"area":"import","title":"Import origin","titleKm":"ប្រភពនាំចូល","status":"VERIFIED","detail":"Import declaration from Dubai was verified and matches the declared import origin.","detailKm":"លិខិតប្រកាសនាំចូលពីឌូបាយត្រូវបានផ្ទៀងផ្ទាត់ ដែលត្រូវនឹងប្រភពនាំចូលដែលបានប្រកាស។","source":"Import declaration (platform-verified)","confidence":0.9},{"area":"mileage","title":"Odometer & mileage","titleKm":"ចំនួនគីឡូម៉ែត្រ","status":"EVIDENCE_FOUND","detail":"Odometer of 89,000 km is plausible for a 2018 vehicle (about 11,100 km/year) and is consistent with service records covering 2019-2024. No independent odometer database check was possible.","detailKm":"៨៩,០០០ គ.ម មានភាពសមរម្យសម្រាប់ឡានឆ្នាំ២០១៨ (~១១,១០០ គ.ម/ឆ្នាំ) និងត្រូវគ្នានឹងកំណត់ហេតុសេវាកម្ម ២០១៩–២០២៤ ទោះបីគ្មានការពិនិត្យទិន្នន័យ odometer ដោយឯករាជ្យក៏ដោយ។","source":"Service records + Listing data","confidence":0.8},{"area":"price","title":"Price vs market","titleKm":"តម្លៃធៀបទីផ្សារ","status":"EVIDENCE_FOUND","detail":"$52,500 sits within the typical range for 2018 Prado TX diesel units in Phnom Penh ($48,000-$57,000 based on current comparable listings).","detailKm":"៥២,៥០០ ដុល្លាស្ថិតក្នុងជួរតម្លៃទីផ្សារសម្រាប់ Prado TX ស្លាបប្រេងសាឺតឆ្នាំ២០១៨ នៅភ្នំពេញ (៤៨,០០០–៥៧,០០០ ដុល្លាតាមបញ្ជីប្រៀបធៀប)។","source":"Market comparables","confidence":0.8},{"area":"service","title":"Service history","titleKm":"ប្រវត្តិថែទាំ","status":"EVIDENCE_FOUND","detail":"Authorized workshop service records covering 2019-2024 were provided and show regular maintenance.","detailKm":"កំណត់ហេតុសេវាកម្មពីរោងចក្រផ្លូវការឆ្នាំ ២០១៩–២០២៤ ត្រូវបានផ្ដល់ជូន ហើយបង្ហាញការថែទាំទាន់ពេល។","source":"Service records (provided)","confidence":0.8},{"area":"photos","title":"Photos vs description","titleKm":"រូបភាពធៀបការប្រកាស","status":"EVIDENCE_FOUND","detail":"Listing photos are consistent with the described condition (new tires, clean interior); no visible mismatch with the declared color or trim.","detailKm":"រូបភាពត្រូវគ្នានឹងការប្រកាស (កង់ថ្មី ខាងក្នុងស្អាត) ហើយគ្មានភាពមិនត្រូវគ្នាជាមួយពណ៌ ឬកម្រិតបរិក្ខារ។","source":"Listing photo analysis","confidence":0.75},{"area":"ownership","title":"Ownership history","titleKm":"ប្រវត្តិម្ចាស់ភាព","status":"EVIDENCE_FOUND","detail":"Registration book shows 2 registered owners, consistent with the seller''s declared ownership count.","detailKm":"សៀវភៅចុះបញ្ជីបង្ហាញម្ចាស់ចំនួន ២ នាក់ ត្រូវនឹងចំនួនដែលអ្នកលក់ប្រកាស។","source":"Registration book (platform-verified)","confidence":0.85},{"area":"accident","title":"Accident records","titleKm":"កំណត់ហេតុគ្រោះថ្នាក់","status":"NOT_VERIFIED","detail":"Seller declares no accidents. This is a declaration only — it is not independent verification, and no official accident database was checked.","detailKm":"អ្នកលក់ប្រកាសថាគ្មានគ្រោះថ្នាក់ចរាចរ។ នេះជាការប្រកាសតែប៉ុណ្ណោះ — មិនមែនជាការផ្ទៀងផ្ទាត់ដោយឯករាជ្យ ហើយគ្មានមូលដ្ឋានទិន្នន័យគ្រោះថ្នាក់ផ្លូវការណ៍ណាមួយត្រូវបានពិនិត្យទេ។","source":"Seller declaration","confidence":0.45},{"area":"listing","title":"Listing quality & safety","titleKm":"គុណភាពបញ្ជី និងសុវត្ថិភាព","status":"EVIDENCE_FOUND","detail":"Listing text is detailed and consistent across fields (year, mileage, documents). No scam-pattern language detected.","detailKm":"អត្ថបទបញ្ជីលក់មានព័ត៌មានលម្អិត និងត្រូវគ្នារវាងវាលនីមួយៗ (ឆ្នាំ គ.ម ឯកសារ)។ រកមិនឃើញលក្ខណៈសញ្ញានៃការបញ្ឆោតទេ។","source":"Listing text analysis","confidence":0.85}]', 78.0, 'This 2018 Prado TX presents well: the registration book and Dubai import declaration are platform-verified, and service records from 2019-2024 support the 89,000 km odometer. The seller declares no accidents, but that remains an unverified declaration. Overall the listing is consistent and transparent for its class.', 'ឡាន Prado TX ឆ្នាំ២០១៨ នេះមានលក្ខណៈល្អ៖ សៀវភៅចុះបញ្ជី និងលិខិតប្រកាសនាំចូលពីឌូបាយ ត្រូវបានផ្ទៀងផ្ទាត់ដោយវេទិកាហើយ ហើយកំណត់ហេតុសេវាកម្មឆ្នាំ២០១៩–២០២៤ គាំទ្រចំនួន ៨៩,០០០ គ.ម។ អ្នកលក់ប្រកាសថាគ្មានគ្រោះថ្នាក់ចរាចរ ប៉ុន្តែការប្រកាសនេះមិនទាន់បានផ្ទៀងផ្ទាត់ដោយឯករាជ្យទេ។ ជារួម បញ្ជីលក់នេះមានភាពទៀងទាត់ និងគួរឱ្យទុកចិត្ត។', '[{"en":"This report analyzes listing information and provided documents only. It is not a physical inspection.","km":"របាយការណ៍នេះវិភាគតែពីព័ត៌មានបញ្ជាក់ និងឯកសារដែលផ្ដល់ជូនប៉ុណ្ណោះ។ វាមិនមែនជាការពិនិត្យរថយន្តដោយផ្ទាល់ទេ។"},{"en":"''No records found'' does not mean ''no accidents'' or ''no problems''.","km":"''រកមិនឃើញទិន្នន័យ'' មិនមែនមានន័យថា ''គ្មានគ្រោះថ្នាក់'' ឬ ''គ្មានបញ្ហា'' ទេ។"},{"en":"AI observations are probabilistic and may be wrong. Always inspect the vehicle in person.","km":"ការវិភាគដោយ AI អាចមានកំហុស។ សូមពិនិត្យរថយន្តដោយខ្លួនឯងជានិច្ច។"},{"en":"Report results reflect the data available at generation time and may become outdated.","km":"លទ្ធផលរបាយការណ៍ឆ្លុះបញ្ចាំងតែទិន្នន័យនៅពេលបង្កើតប៉ុណ្ណោះ ហើយអាចមិនទាន់សម័យនៅពេលក្រោយ។"}]', 'COMPLETE', NULL, to_timestamp(1792484764079 / 1000.0)) ON CONFLICT DO NOTHING;
INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvhul6eq002uoz9nw8i2iqz3', 'veh_lexus_rx350', '[{"area":"identity","title":"VIN & identity","titleKm":"អត្តសញ្ញាណ និងលេខសំគាល់","status":"NOT_VERIFIED","detail":"Chassis ending 5T4119 from the listing could not be cross-checked against a physical inspection or an independent VIN database.","detailKm":"លេខចាប់ចុង 5T4119 ពីបញ្ជីលក់មិនអាចផ្ទៀងផ្ទាត់ជាមួយការពិនិត្យដោយផ្ទាល់ ឬមូលដ្ឋានទិន្នន័យ VIN ឯករាជ្យបានទេ។","source":"Listing data","confidence":0.45},{"area":"registration","title":"Registration book","titleKm":"សៀវភៅចុះបញ្ជី","status":"EVIDENCE_FOUND","detail":"Registration book was provided and reviewed. Plate 2AB-1194 and the 3-owner history look consistent. Provided documents are reviewed but not platform-verified.","detailKm":"សៀវភៅចុះបញ្ជីត្រូវបានផ្ដល់ជូននិងបានពិនិត្យ។ ស្លាកលេខ 2AB-1194 និងប្រវត្តិម្ចាស់ ៣ នាក់មើលទៅត្រូវគ្នា។ ឯកសារដែលផ្ដល់ជូនត្រូវបានពិនិត្យ ប៉ុន្តែមិនត្រូវបានផ្ទៀងផ្ទាត់ដោយវេទិកាទេ។","source":"Registration book (provided)","confidence":0.7},{"area":"import","title":"Import origin","titleKm":"ប្រភពនាំចូល","status":"EVIDENCE_FOUND","detail":"US import declaration was provided; the declared USA origin is consistent with a left-hand-drive RX 350.","detailKm":"លិខិតប្រកាសនាំចូលពីអាមេរិកត្រូវបានផ្ដល់ជូន ហើយប្រភព USA ត្រូវគ្នានឹង RX 350 ចង្កឹះឆ្វេង។","source":"Import declaration (provided)","confidence":0.7},{"area":"mileage","title":"Odometer & mileage","titleKm":"ចំនួនគីឡូម៉ែត្រ","status":"NOT_VERIFIED","detail":"118,000 km over about 9 years (~13,100 km/year) is on the higher side for Phnom Penh but plausible. No odometer history database was available to rule out rollbacks.","detailKm":"១១៨,០០០ គ.ម ក្នុងរយៈពេល ~៩ ឆ្នាំ (~១៣,១០០ គ.ម/ឆ្នាំ) ខ្ពស់បន្តិចសម្រាប់ភ្នំពេញ ប៉ុន្តែមានភាពអាចកើតមាន។ គ្មានទិន្នន័យ odometer ឯករាជ្យដើម្បីបញ្ជាក់ថាគ្មានការកែចំនួនគ.មទេ។","source":"Listing data","confidence":0.5},{"area":"price","title":"Price vs market","titleKm":"តម្លៃធៀបទីផ្សារ","status":"EVIDENCE_FOUND","detail":"$34,900 is within the typical market band for 2015 RX 350 imports in Phnom Penh ($32,000-$38,000).","detailKm":"៣៤,៩០០ ដុល្លាស្ថិតក្នុងជួរទីផ្សារសម្រាប់ RX 350 ឆ្នាំ២០១៥ នៅភ្នំពេញ (៣២,០០០–៣៨,០០០ ដុល្លា)។","source":"Market comparables","confidence":0.75},{"area":"service","title":"Service history","titleKm":"ប្រវត្តិថែទាំ","status":"NO_DATA","detail":"No service records were provided, so maintenance history could not be assessed. Missing records are common but reduce transparency.","detailKm":"គ្មានកំណត់ហេតុសេវាកម្មត្រូវបានផ្ដល់ជូន ដូច្នេះប្រវត្តិថែទាំមិនអាចវាយតម្លៃបានទេ។ ការបាត់បង់កំណត់ហេតុគឺធម្មតា ប៉ុន្តែកាត់បន្ថយភាពច្បាស់លាស់។","source":"No documents provided","confidence":0.3},{"area":"photos","title":"Photos vs description","titleKm":"រូបភាពធៀបការប្រកាស","status":"EVIDENCE_FOUND","detail":"Photos show the described leather and navigation in good condition; the rear bumper appears repaired, consistent with the declared minor damage.","detailKm":"រូបភាពបង្ហាញស្បែក និងប្រព័ន្ធនាវាចរណ៍ក្នុងស្ថានភាពល្អដូចការប្រកាស។ ស្ពានក្រោយដែលបានជួសជុលត្រូវគ្នានឹងការប្រកាស។","source":"Listing photo analysis","confidence":0.65},{"area":"ownership","title":"Ownership history","titleKm":"ប្រវត្តិម្ចាស់ភាព","status":"EVIDENCE_FOUND","detail":"Registration book indicates 3 owners, matching the declared ownership count of 3.","detailKm":"សៀវភៅចុះបញ្ជីបង្ហាញម្ចាស់ ៣ នាក់ ត្រូវនឹងចំនួនដែលបានប្រកាស។","source":"Registration book (provided)","confidence":0.75},{"area":"accident","title":"Accident records","titleKm":"កំណត់ហេតុគ្រោះថ្នាក់","status":"EVIDENCE_FOUND","detail":"Seller declares minor rear-bumper damage; ask for repair documentation. Photos are consistent with a repaired bumper, but severity cannot be confirmed from the listing alone.","detailKm":"អ្នកលក់ប្រកាសថាមានគ្រោះថ្នាក់តូចនៅស្ពានក្រោយ។ សូមសុំឯកសារជួសជុល។ រូបភាពត្រូវគ្នានឹងស្ពានដែលបានជួសជុល ប៉ុន្តែកម្រិតខាតបង់មិនអាចបញ្ជាក់ពីបញ្ជីតែមួយបានទេ។","source":"Seller declaration + Listing photos","confidence":0.6},{"area":"listing","title":"Listing quality & safety","titleKm":"គុណភាពបញ្ជី និងសុវត្ថិភាព","status":"EVIDENCE_FOUND","detail":"Listing is complete and honest about prior damage, a positive trust signal. No scam-pattern language detected.","detailKm":"បញ្ជីលក់ពេញលេញ និងត្រង់នៃការប្រកាសគ្រោះថ្នាក់ពីមុន ដែលជាសញ្ញាវិជ្ជមាន។ រកមិនឃើញលក្ខណៈសញ្ញាបញ្ឆោតទេ។","source":"Listing text analysis","confidence":0.75}]', 62.0, 'This 2015 RX 350 is honestly listed: the seller openly declares minor rear-bumper damage and provides registration and import documents that match the declared 3-owner history. However, the mileage could not be independently verified and no service records exist. A pre-purchase inspection with a trusted mechanic is strongly recommended.', 'ឡាន RX 350 ឆ្នាំ២០១៥ នេះត្រូវបានប្រកាសដោយត្រង់៖ អ្នកលក់ប្រកាសចំហថាមានគ្រោះថ្នាក់តូចនៅស្ពានក្រោយ ហើយផ្ដល់ឯកសារចុះបញ្ជី និងនាំចូល ដែលត្រូវគ្នានឹងម្ចាស់ចំនួន ៣ នាក់។ ទោះជាយ៉ាងណា ចំនួនគ.មមិនអាចផ្ទៀងផ្ទាត់ដោយឯករាជ្យបានទេ ហើយគ្មានកំណត់ហេតុសេវាកម្មទេ។ សូមពិនិត្យឡានជាមួយគ្រូបង្គោលមុនពេលទិញ។', '[{"en":"This report analyzes listing information and provided documents only. It is not a physical inspection.","km":"របាយការណ៍នេះវិភាគតែពីព័ត៌មានបញ្ជាក់ និងឯកសារដែលផ្ដល់ជូនប៉ុណ្ណោះ។ វាមិនមែនជាការពិនិត្យរថយន្តដោយផ្ទាល់ទេ។"},{"en":"''No records found'' does not mean ''no accidents'' or ''no problems''.","km":"''រកមិនឃើញទិន្នន័យ'' មិនមែនមានន័យថា ''គ្មានគ្រោះថ្នាក់'' ឬ ''គ្មានបញ្ហា'' ទេ។"},{"en":"AI observations are probabilistic and may be wrong. Always inspect the vehicle in person.","km":"ការវិភាគដោយ AI អាចមានកំហុស។ សូមពិនិត្យរថយន្តដោយខ្លួនឯងជានិច្ច។"},{"en":"Report results reflect the data available at generation time and may become outdated.","km":"លទ្ធផលរបាយការណ៍ឆ្លុះបញ្ចាំងតែទិន្នន័យនៅពេលបង្កើតប៉ុណ្ណោះ ហើយអាចមិនទាន់សម័យនៅពេលក្រោយ។"}]', 'COMPLETE', NULL, to_timestamp(1792484764082 / 1000.0)) ON CONFLICT DO NOTHING;
