INSERT INTO messages ("id", "conversation_id", "sender_id", "body", "is_system", "created_at") VALUES ('cmvhul6et002voz9nqsoop9p0', 'conv_demo_1', NULL, 'គន្លឹះសុវត្ថិភាព: កុំបង់ប្រាក់ដុនមុនពេលមើលឡាននិងឯកសារ។ ជួបកន្លែងមានគេច្រើន ហើយនាំគ្រូបង្គោលមកពិនិត្យជាមួយ។ / Safety tip: Never pay a deposit before seeing the car and documents. Meet in a public place and bring a trusted mechanic.', TRUE, to_timestamp(1792401964084 / 1000.0)) ON CONFLICT DO NOTHING;
INSERT INTO messages ("id", "conversation_id", "sender_id", "body", "is_system", "created_at") VALUES ('cmvhul6et002woz9njypsde02', 'conv_demo_1', 'usr_demo_buyer', 'សួស្តី ឡាននៅមានទេ? ចង់ដឹងថាអាចមកមើលថ្ងៃសៅរ៍បានទេ? / Hello, is the car still available? Can I come see it Saturday?', FALSE, to_timestamp(1792477564084 / 1000.0)) ON CONFLICT DO NOTHING;
